-- Sounds: every sound effect and music track used by the client.
-- `id` = your uploaded asset id (e.g. "rbxassetid://123"). Upload assets/sfx/*.wav (generated by tools/gen_sfx.py)
-- through the Creator Hub, then paste the ids here. Until then `fallback` (a built-in Roblox sound) is used.
-- group: UI | SFX | Music | Ambience  (each has its own volume slider in Settings)
local S = {}
local function add(name, group, volume, fallback, extra)
	local def = { name = name, id = "", group = group, volume = volume, fallback = fallback }
	if extra then
		for k, v in pairs(extra) do
			def[k] = v
		end
	end
	S[name] = def
end

local CLICK = "rbxasset://sounds/clickfast.wav"
local PING = "rbxasset://sounds/electronicpingshort.wav"
local SWORD = "rbxasset://sounds/swordslash.wav"
local HIT = "rbxasset://sounds/hit.wav"
local BOOM = "rbxasset://sounds/collide.wav"
local SPLASH = "rbxasset://sounds/impact_water.mp3"
local SHOT = "rbxasset://sounds/Rocket shot.wav"

-- UI
add("UIHover", "UI", 0.25, CLICK, { pitch = 1.6 })
add("UIClick", "UI", 0.5, CLICK)
add("UIOpen", "UI", 0.45, PING, { pitch = 0.8 })
add("UIClose", "UI", 0.4, PING, { pitch = 0.6 })
add("Error", "UI", 0.5, "rbxasset://sounds/uuhhh.mp3", { pitch = 1.4 })
add("Coin", "UI", 0.4, PING, { pitch = 0.72 }) -- the synth coin is high: play it lower (the owner found it shrill)
add("Purchase", "UI", 0.55, PING, { pitch = 1.25 })
add("Equip", "UI", 0.5, "rbxasset://sounds/unsheath.wav")
-- Progression
add("LevelUp", "SFX", 0.7, PING, { pitch = 1.1 })
for i, tier in ipairs({ "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Secret" }) do
	add("Rarity" .. tier, "SFX", 0.45 + i * 0.05, PING, { pitch = 0.8 + i * 0.1 })
end
add("CardDrop", "SFX", 0.7, PING, { pitch = 1.8 })
add("RefineSuccess", "SFX", 0.7, PING, { pitch = 1.3 })
add("RefineFail", "SFX", 0.6, BOOM, { pitch = 0.7 })
add("RefineBreak", "SFX", 0.7, "rbxasset://sounds/glassbreak.wav")
add("AnvilClang", "SFX", 0.6, "rbxasset://sounds/clickfast.wav", { pitch = 0.9 })
-- Combat
add("Hit", "SFX", 0.42, HIT, { pitch = 0.82 })
add("Crit", "SFX", 0.55, HIT, { pitch = 1.05 })
add("Slash", "SFX", 0.45, SWORD)
add("Whoosh", "SFX", 0.4, "rbxasset://sounds/swordlunge.wav")
add("MagicCast", "SFX", 0.5, PING, { pitch = 0.7 })
add("Heal", "SFX", 0.5, PING, { pitch = 1.6 })
add("MonsterDie", "SFX", 0.5, "rbxasset://sounds/splat.wav", { pitch = 0.85 })
add("ChestOpen", "SFX", 0.6, PING, { pitch = 0.75, alias = "Purchase" }) -- a lower take on the purchase jingle
add("ChestRattle", "SFX", 0.55, "rbxasset://sounds/clickfast.wav", { pitch = 0.9 })
add("BossRoar", "SFX", 0.8, BOOM, { pitch = 0.4 })
-- Sea
add("Cannon", "SFX", 0.75, SHOT, { pitch = 0.6, rolloff = 600 })
add("Explosion", "SFX", 0.8, BOOM, { pitch = 0.5, rolloff = 700 })
add("Splash", "SFX", 0.6, SPLASH, { rolloff = 500 })
add("ShipHit", "SFX", 0.7, BOOM, { pitch = 0.8, rolloff = 500 })
add("ShipCreak", "SFX", 0.35, BOOM, { pitch = 0.3 })
add("Bell", "SFX", 0.6, PING, { pitch = 0.5 })
-- Loops
add("AmbienceSea", "Ambience", 0.35, "", { looped = true })
add("AmbienceWind", "Ambience", 0.25, "", { looped = true })
add("MusicIsland", "Music", 0.35, "", { looped = true })
add("MusicSea", "Music", 0.35, "", { looped = true })
add("MusicBoss", "Music", 0.45, "", { looped = true })











